 "content": "from collections import Counter


def transform(grid):
    """Fill erased cells in a cyclic color field with a one-step diagonal offset."""
    h, w = len(grid), len(grid[0])
    colors = sorted({v for row in grid for v in row if v != 0})
    if not colors:
        return [row[:] for row in grid]
    predecessor = {colors[i]: colors[(i - 1) % len(colors)] for i in range(len(colors))}

    # Away from the top row and main diagonal, each column shows the same
    # underlying cycle value; use its visible majority to recover that value.
    column_value = []
    for c in range(w):
        observed = [grid[r][c] for r in range(1, h) if r != c and grid[r][c] != 0]
        if not observed:
            observed = [grid[r][c] for r in range(h) if grid[r][c] != 0]
        column_value.append(Counter(observed).most_common(1)[0][0])

    out = [row[:] for row in grid]
    for r in range(h):
        for c in range(w):
            if out[r][c] == 0:
                value = column_value[c]
                out[r][c] = predecessor[value] if r == 0 or r == c else value
    return out
